# spec_artifact_hash attestation GROUNDWORK — ES Appendix O.4 (release
# attestation record, schema appname.releaseAttestation.v1) + Appendix I.4
# (the spec_artifact_hash / BLAKE3 fingerprint). Plan §2.5 "Release
# engineering": "spec_artifact_hash stamped attestation groundwork".
#
# WHAT THIS IS (honest scope). Appendix O.4 says the ONE release-attestation
# record is generated by the release pipeline, GPG-signed, and its
# specArtifactHash is recomputed from the TAGGED spec tree and MUST match
# the Appendix I.4 stamp (checklist step 7a). This build is NOT tagged for
# CP-1.0 (row-zero-gated: O-WATCH pre-tag PASS + operator word), so this is
# the GROUNDWORK: the stamp mechanism, exercised against the frozen bogos
# v5.5 spec tree, plus the attestation SKELETON with the fields this lane
# owns filled and the cross-lane / release-time fields marked `pending:` with
# their completion mechanism named. No value is ever invented (V44 posture).
#
# THE STAMP. The frozen bogos v5.5 spec_artifact_hash is pinned below as the
# EXPECTED value, computed 2026-08-18 from the spec source tree via the
# spec's own tools/spec_validate.py --hash (canonical BLAKE3, its --selftest
# green against the official BLAKE3 vectors). `--verify` recomputes it from
# the spec tree when reachable and asserts equality; at real release the
# input is the tagged tree.
#
# USAGE:
#   tools/gen_attestation.py --verify [--spec-tree DIR]   recompute + assert
#   tools/gen_attestation.py --emit   [--out FILE]        write the skeleton
#   tools/gen_attestation.py --print-frozen-hash          the pinned value

import argparse
import hashlib
import os
import subprocess
import sys

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Frozen bogos v5.5 spec_artifact_hash — canonical BLAKE3 (Appendix I.4),
# computed from the spec source tree 2026-08-18 via bogos/tools/spec_validate.py
# --hash (that tool's --selftest verified green: framing vector + official
# BLAKE3 empty + 1024-byte-pattern known answers).
FROZEN_SPEC_VERSION = "5.5"
FROZEN_SPEC_ARTIFACT_HASH = (
    "blake3:50ff1ea3c8971ea20b504655eea42dc46a90a6caead36b4924dbc58ec318104b"
)

# Candidate locations of the spec source tree (the recompute input). A real
# release passes the tagged checkout explicitly via --spec-tree.
SPEC_TREE_CANDIDATES = [
    os.environ.get("APPNAME_SPEC_TREE", ""),
    os.path.join(REPO, "..", "..", "bogos"),
    os.path.join(REPO, "..", "bogos"),
]


def sh(cmd, cwd=None):
    return subprocess.run(
        cmd, cwd=cwd, capture_output=True, text=True
    )


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def find_spec_tree(explicit=None):
    cands = ([explicit] if explicit else []) + SPEC_TREE_CANDIDATES
    for c in cands:
        if c and os.path.isfile(os.path.join(c, "tools", "spec_validate.py")):
            return os.path.abspath(c)
    return None


def recompute_spec_hash(spec_tree):
    r = sh([sys.executable, "tools/spec_validate.py", "--hash"], cwd=spec_tree)
    if r.returncode not in (0, 2):  # 0 canonical, 2 noncanonical
        raise RuntimeError(f"spec_validate.py --hash failed: {r.stderr.strip()}")
    line = r.stdout.strip().splitlines()[-1].strip()
    canonical = r.returncode == 0
    return line, canonical


def cmd_verify(args):
    spec_tree = find_spec_tree(args.spec_tree)
    expected = FROZEN_SPEC_ARTIFACT_HASH.split(":", 1)[1]
    if not spec_tree:
        print(
            "attestation --verify: SKIP — spec source tree not reachable "
            "(set APPNAME_SPEC_TREE or --spec-tree). Pinned frozen v%s hash "
            "stands: %s. Recompute at release from the tagged spec tree "
            "(O.4 step 7a)." % (FROZEN_SPEC_VERSION, FROZEN_SPEC_ARTIFACT_HASH)
        )
        return 0
    got, canonical = recompute_spec_hash(spec_tree)
    print(f"spec tree:  {spec_tree}")
    print(f"expected:   blake3:{expected}")
    print(f"recomputed: {got}  ({'canonical BLAKE3' if canonical else 'NONCANONICAL'})")
    if not canonical:
        print("attestation --verify: FAIL — recomputed hash is NONCANONICAL "
              "(no BLAKE3 backend); a release hash MUST be canonical (VAL-001).")
        return 1
    if got == expected:
        print("attestation --verify: PASS — recomputed spec_artifact_hash equals "
              "the pinned frozen v%s stamp (O.4 step 7a mechanism)." % FROZEN_SPEC_VERSION)
        return 0
    print("attestation --verify: FAIL — recomputed hash != pinned frozen stamp. "
          "The recorded value is evidence of what shipped and is NEVER edited "
          "(I.4); investigate as an artifact-drift incident (Appendix K).")
    return 1


def sbom_digest():
    """Combined digest over the sorted per-crate SBOM set (groundwork stand-in
    for the per-leg release sbom.cdx.json sha256 of O.3/O.4). The real release
    records one sha256 per OS/arch leg's single published SBOM."""
    sbom_dir = os.path.join(REPO, "sbom")
    if not os.path.isdir(sbom_dir):
        return None, 0
    files = sorted(f for f in os.listdir(sbom_dir) if f.endswith(".cdx.json"))
    if not files:
        return None, 0
    h = hashlib.sha256()
    for f in files:
        h.update(f.encode())
        h.update(b"\0")
        h.update(sha256_file(os.path.join(sbom_dir, f)).encode())
        h.update(b"\0")
    return h.hexdigest(), len(files)


def git(*a):
    r = sh(["git", *a], cwd=REPO)
    return r.stdout.strip() if r.returncode == 0 else ""


def walled_symbols_status():
    """Derive the D-44 release-assertion status by INVOKING the check (not
    asserting it): pass / fail(critical) / pending(no artifacts built)."""
    script = os.path.join(REPO, "tools", "walled_symbols_release.sh")
    if not os.path.isfile(script):
        return "pending", "tools/walled_symbols_release.sh absent"
    r = sh(["bash", script, "--no-build"], cwd=REPO)
    return _classify_walled(r.returncode, (r.stdout or "") + (r.stderr or ""))


def _classify_walled(returncode, out):
    """Map the tripwire's (rc, output) to an attestation status.

    Split out of walled_symbols_status 2026-09-05 so it can be driven directly
    by --selftest: the bug below could not be tested while the classification
    was welded to a subprocess call.

    THE DEFECT (O-WATCH #484, O-INT entries 645/646; operator assignment
    2026-09-05 19:15 ET, item 8 link 4): this returned CRITICAL for ANY
    non-zero rc it did not recognise. A harness that dies with EMPTY output --
    which is exactly what walled_symbols_release.sh did whenever its last
    artifact was missing -- fell past the "no shipped release artifacts found"
    test *because the output was empty* and was attested as
    "a gated/walled symbol is present in a shipped artifact".

    A MISSING BUILD FILE WAS REPORTED AS A SHIPPED GATED SYMBOL, in the
    document a release ships with.

    The rule now: a CRITICAL requires POSITIVE EVIDENCE. The tripwire prints a
    line carrying "CRITICAL" on every real violation (walled_symbols_release.sh
    lines 308 and 317). Without that evidence an unrecognised failure is what
    it actually is -- a check that did not reach a verdict. It still BLOCKS
    (status "fail", fail-safe), but it no longer asserts a finding nobody
    measured.
    """
    if returncode == 0:
        return "pass", "tools/walled_symbols_release.sh --no-build (D-44 gated symbols absent)"
    if "no shipped release artifacts found" in out:
        return "pending", "release artifacts not built — run cargo build --release --workspace then re-emit"
    if "CRITICAL" in out:
        return "fail", "CRITICAL — a gated/walled symbol is present in a shipped artifact (D-44 STOP)"
    return "fail", (
        "INCONCLUSIVE — the D-44 check did not reach a verdict (rc=%d, %d bytes of output, "
        "no CRITICAL and no artifact-set message). This is a HARNESS failure, not a symbol "
        "finding; it blocks promotion and must not be read as one." % (returncode, len(out))
    )


def cmd_emit(args):
    commit = git("rev-parse", "HEAD")
    describe = git("describe", "--tags") or "(untagged)"
    epoch = git("log", "-1", "--format=%ct", "HEAD")
    rustc = ""
    r = sh(["rustc", "--version"])
    if r.returncode == 0:
        rustc = r.stdout.strip()
    toolchain_sha = sha256_file(os.path.join(REPO, "rust-toolchain.toml"))
    cargo_lock_sha = sha256_file(os.path.join(REPO, "Cargo.lock"))
    notices_sha = sha256_file(os.path.join(REPO, "THIRD-PARTY-NOTICES.md"))
    sbom_hash, sbom_n = sbom_digest()

    lines = []
    p = lines.append
    p("# appname spec artifact — generated-from: ENGINEERING-SPEC.md Appendix O.4")
    p("# schema: appname.releaseAttestation.v1   authority: artifact")
    p("# GROUNDWORK (plan §2.5) — NOT a signed release record. CP-1.0 is not")
    p("# tagged (row-zero-gated: O-WATCH pre-tag PASS + operator word). Fields")
    p("# this lane owns are filled; cross-lane / release-time fields are")
    p("# `pending:` with their completion mechanism named. No value invented (V44).")
    p("schema: appname.releaseAttestation.v1")
    p("release:")
    p(f"  gitTag: {describe}          # CP-1.0 tag pending row-zero gate")
    p(f"  gitCommit: {commit}")
    p(f"  date: {epoch}               # SOURCE_DATE_EPOCH of HEAD (O.1); tag %ct at release")
    p("  tagSignedByFingerprint: pending  # release signing key (§33.4 custody)")
    p("toolchain:")
    p(f"  rustcVersion: {rustc}")
    p(f"  rustToolchainTomlSha256: {toolchain_sha}")
    p("  cbindgenVersion: pending    # deps/cbindgen.yaml pin at packaging")
    p("  cargoLockSha256: %s" % cargo_lock_sha)
    p("  ciImageDigests: pending     # no pinned CI container on this host (O.1)")
    p("spec:")
    p(f'  specVersion: "{FROZEN_SPEC_VERSION}"')
    p(f"  specArtifactHash: {FROZEN_SPEC_ARTIFACT_HASH}   # Appendix I.4; --verify recomputes")
    p("sbom:")
    if sbom_hash:
        p(f"  workspaceSbomSetSha256: {sbom_hash}   # groundwork: sha256 over the {sbom_n} sorted per-crate cdx files")
        p("  # release records one sha256 per OS/arch leg's published sbom.cdx.json (O.3/O.4)")
    else:
        p("  workspaceSbomSetSha256: pending  # run scripts/gen_sbom.sh (sbom/ is gitignored)")
    p("thirdPartyNoticesSha256: %s" % notices_sha)
    p("goldenBaselineSetHash: pending  # BLAKE3 over §34.1 LFS baseline hashes — O-QA owns goldens")
    p("reproVerify:")
    p("  status: pending             # tools/repro-verify.sh under the O.1 container; blocks promotion (O.4 step 10a)")
    p("  allowlistSha256: %s" % sha256_file(os.path.join(REPO, "tools", "repro", "allowlist.toml")))
    ws_status, ws_note = walled_symbols_status()
    p("walledSymbolsRelease:")
    p(f"  status: {ws_status}   # {ws_note}")
    p("gates:")
    p("  abiConformance: pending     # Appendix N release tier (O-SCRIPT/cabi)")
    p("  workflowCatalog: pending    # W1–W27 release tier (§41.8, O-QA)")
    p("signoffs: pending             # release / qa-infra / security / legal-governance (Appendix K.1) — human accountables at release")
    # OPERATOR WORD 9 (2), 2026-09-14 18:46 ET — AMENDMENT 11 (e). Until today this
    # document attested a COMMIT and a TOOLCHAIN and named no artifact at all, so
    # "the artifact that was built and attested" was true of its first half only
    # (OB-70, measured on the shipped dmg 2026-09-14 17:0x). Every artifact now
    # appears with its size and SHA-256. No value is invented: with no --artifacts-dir
    # the section says `pending` and names the mechanism, exactly as the rest do.
    p("artifacts:")
    if args.artifacts_dir:
        d = os.path.abspath(args.artifacts_dir)
        if not os.path.isdir(d):
            sys.exit(f"gen_attestation: --artifacts-dir is not a directory: {d}")
        names = sorted(n for n in os.listdir(d) if os.path.isfile(os.path.join(d, n)))
        if not names:
            sys.exit(f"gen_attestation: --artifacts-dir holds no files: {d} — "
                     "an empty artifacts block is not an attestation")
        p(f"  set: {os.path.basename(d)}   # {len(names)} artifacts, enumerated at emit time")
        for n in names:
            fp = os.path.join(d, n)
            p(f"  - name: {n}")
            p(f"    sizeBytes: {os.path.getsize(fp)}")
            p(f"    sha256: {sha256_file(fp)}")
    else:
        p("  pending   # re-emit with --artifacts-dir <release set> once the set is assembled"
          " (build_dmg.sh stage 9)")

    out = "\n".join(lines) + "\n"
    if args.out:
        with open(args.out, "w") as f:
            f.write(out)
        print(f"attestation groundwork written: {args.out}")
    else:
        sys.stdout.write(out)
    return 0


def cmd_selftest(args):
    """Drive _classify_walled with the four shapes it must separate.

    The MUST-FIRE arm is the fourth: revert _classify_walled to its old form
    (drop the "CRITICAL" test and the INCONCLUSIVE return) and it goes red,
    because rc!=0 with empty output falls straight back into the CRITICAL
    branch. Written against O-WATCH #484 / entries 645/646.
    """
    cases = [
        ("rc 0, normal output",
         0, "walled-symbols-release: all shipped artifacts PASS", "pass", None),
        ("rc 1, artifacts absent (CONTROL: the pending path)",
         1, "walled-symbols-release: FAIL — no shipped release artifacts found under target/release/",
         "pending", None),
        ("rc 1, a REAL violation (CONTROL: CRITICAL still reachable)",
         1, "walled-symbols-release: CRITICAL — gated/walled symbol present in target/release/appname",
         "fail", "CRITICAL"),
        ("rc 1, EMPTY output — the crashed harness (MUST FIRE)",
         1, "", "fail", "INCONCLUSIVE"),
    ]
    fails = 0
    for label, rc, out, want_status, want_marker in cases:
        status, note = _classify_walled(rc, out)
        ok = (status == want_status) and (want_marker is None or note.startswith(want_marker))
        print("%s %-52s -> %s / %s" % ("PASS:" if ok else "FAIL:", label, status, note[:44]))
        if not ok:
            fails += 1
    # The point of the fourth case, stated so a reader cannot miss it.
    _, note = _classify_walled(1, "")
    if "gated/walled symbol is present" in note:
        print("FAIL: a crashed harness is still attested as a shipped gated symbol")
        fails += 1
    print("gen_attestation --selftest: %d cases, %d failed" % (len(cases), fails))
    return 1 if fails else 0


def main():
    ap = argparse.ArgumentParser(description="spec_artifact_hash attestation groundwork (Appendix O.4)")
    g = ap.add_mutually_exclusive_group(required=True)
    g.add_argument("--verify", action="store_true", help="recompute frozen hash + assert equality")
    g.add_argument("--emit", action="store_true", help="write the attestation skeleton")
    g.add_argument("--print-frozen-hash", action="store_true")
    g.add_argument("--selftest", action="store_true", help="drive _classify_walled with the four shapes")
    ap.add_argument("--spec-tree", default=None, help="spec source tree (recompute input)")
    ap.add_argument("--out", default=None, help="write skeleton here instead of stdout")
    ap.add_argument("--artifacts-dir", default=None,
                    help="enumerate this directory into the artifacts: block (name, size, sha256)")
    args = ap.parse_args()

    if args.print_frozen_hash:
        print(FROZEN_SPEC_ARTIFACT_HASH)
        return 0
    if args.selftest:
        return cmd_selftest(args)
    if args.verify:
        return cmd_verify(args)
    if args.emit:
        return cmd_emit(args)


if __name__ == "__main__":
    sys.exit(main())
